    89→/// Internal implementation of fetch blobs, which uses `FetchBlobsBeaconAdapter` instead of
    90→/// `BeaconChain` for better testability.
    91→async fn fetch_and_process_engine_blobs_inner<T: BeaconChainTypes>(
    92→    chain_adapter: FetchBlobsBeaconAdapter<T>,
    93→    block_root: Hash256,
    94→    block: Arc<SignedBeaconBlock<T::EthSpec, FullPayload<T::EthSpec>>>,
    95→    custody_columns: &[ColumnIndex],
    96→    publish_fn: impl Fn(EngineGetBlobsOutput<T>) + Send + 'static,
    97→) -> Result<Option<AvailabilityProcessingStatus>, FetchEngineBlobError> {
    98→    let versioned_hashes = if let Some(kzg_commitments) = block
    99→        .message()
   100→        .body()
   101→        .blob_kzg_commitments()
   102→        .ok()
   103→        .filter(|blobs| !blobs.is_empty())
   104→    {
   105→        kzg_commitments
   106→            .iter()
   107→            .map(kzg_commitment_to_versioned_hash)
   108→            .collect::<Vec<_>>()
   109→    } else {
   110→        debug!("Fetch blobs not triggered - none required");
   111→        return Ok(None);
   112→    };
   113→
   114→    debug!(
   115→        num_expected_blobs = versioned_hashes.len(),
   116→        "Fetching blobs from the EL"
   117→    );
   118→
   119→    if chain_adapter
   120→        .spec()
   121→        .is_peer_das_enabled_for_epoch(block.epoch())
   122→    {
   123→        fetch_and_process_blobs_v2(
   124→            chain_adapter,
   125→            block_root,
   126→            block,
   127→            versioned_hashes,
   128→            custody_columns,
   129→            publish_fn,
   130→        )
   131→        .await
   132→    } else {
   133→        fetch_and_process_blobs_v1(
   134→            chain_adapter,
   135→            block_root,
   136→            block,
   137→            versioned_hashes,
   138→            publish_fn,
   139→        )
   140→        .await
   141→    }
   142→}
