   237→#[instrument(skip_all, level = "debug")]
   238→async fn fetch_and_process_blobs_v2<T: BeaconChainTypes>(
   239→    chain_adapter: FetchBlobsBeaconAdapter<T>,
   240→    block_root: Hash256,
   241→    block: Arc<SignedBeaconBlock<T::EthSpec>>,
   242→    versioned_hashes: Vec<VersionedHash>,
   243→    custody_columns_indices: &[ColumnIndex],
   244→    publish_fn: impl Fn(EngineGetBlobsOutput<T>) + Send + 'static,
   245→) -> Result<Option<AvailabilityProcessingStatus>, FetchEngineBlobError> {
   246→    let num_expected_blobs = versioned_hashes.len();
   247→
   248→    metrics::observe(&metrics::BLOBS_FROM_EL_EXPECTED, num_expected_blobs as f64);
   249→    debug!(num_expected_blobs, "Fetching blobs from the EL");
   250→    let response = chain_adapter
   251→        .get_blobs_v2(versioned_hashes)
   252→        .await
   253→        .inspect_err(|_| {
   254→            inc_counter(&metrics::BLOBS_FROM_EL_ERROR_TOTAL);
   255→        })?;
   256→
   257→    let Some(blobs_and_proofs) = response else {
   258→        debug!(num_expected_blobs, "No blobs fetched from the EL");
   259→        inc_counter(&metrics::BLOBS_FROM_EL_MISS_TOTAL);
   260→        return Ok(None);
   261→    };
   262→
   263→    let (blobs, proofs): (Vec<_>, Vec<_>) = blobs_and_proofs
   264→        .into_iter()
   265→        .map(|blob_and_proof| {
   266→            let BlobAndProofV2 { blob, proofs } = blob_and_proof;
   267→            (blob, proofs)
   268→        })
   269→        .unzip();
   270→
   271→    let num_fetched_blobs = blobs.len();
   272→    metrics::observe(&metrics::BLOBS_FROM_EL_RECEIVED, num_fetched_blobs as f64);
   273→
   274→    if num_fetched_blobs != num_expected_blobs {
   275→        // This scenario is not supposed to happen if the EL is spec compliant.
   276→        // It should either return all requested blobs or none, but NOT partial responses.
   277→        // If we attempt to compute columns with partial blobs, we'd end up with invalid columns.
   278→        warn!(
   279→            num_fetched_blobs,
   280→            num_expected_blobs, "The EL did not return all requested blobs"
   281→        );
   282→        inc_counter(&metrics::BLOBS_FROM_EL_MISS_TOTAL);
   283→        return Ok(None);
   284→    }
   285→
   286→    debug!(num_fetched_blobs, "All expected blobs received from the EL");
   287→    inc_counter(&metrics::BLOBS_FROM_EL_HIT_TOTAL);
   288→
   289→    if chain_adapter.fork_choice_contains_block(&block_root) {
   290→        // Avoid computing columns if the block has already been imported.
   291→        debug!(
   292→            info = "block has already been imported",
   293→            "Ignoring EL blobs response"
   294→        );
   295→        return Ok(None);
   296→    }
   297→
   298→    let chain_adapter = Arc::new(chain_adapter);
   299→    let custody_columns_to_import = compute_custody_columns_to_import(
   300→        &chain_adapter,
   301→        block_root,
   302→        block.clone(),
   303→        blobs,
   304→        proofs,
   305→        custody_columns_indices,
   306→    )
   307→    .await?;
   308→
   309→    if custody_columns_to_import.is_empty() {
   310→        debug!(
   311→            info = "No new data columns to import",
   312→            "Ignoring EL blobs response"
   313→        );
   314→        return Ok(None);
   315→    }
   316→
   317→    // Up until this point we have not observed the data columns in the gossip cache, which allows
   318→    // them to arrive independently while this function is running. In publish_fn we will observe
   319→    // them and then publish any columns that had not already been observed.
   320→    publish_fn(EngineGetBlobsOutput::CustodyColumns(
   321→        custody_columns_to_import.clone(),
   322→    ));
   323→
   324→    let availability_processing_status = chain_adapter
   325→        .process_engine_blobs(
   326→            block.slot(),
   327→            block_root,
   328→            EngineGetBlobsOutput::CustodyColumns(custody_columns_to_import),
   329→        )
   330→        .await?;
   331→
   332→    Ok(Some(availability_processing_status))
   333→}
   334→
   335→/// Offload the data column computation to a blocking task to avoid holding up the async runtime.
   336→async fn compute_custody_columns_to_import<T: BeaconChainTypes>(
   337→    chain_adapter: &Arc<FetchBlobsBeaconAdapter<T>>,
   338→    block_root: Hash256,
   339→    block: Arc<SignedBeaconBlock<T::EthSpec, FullPayload<T::EthSpec>>>,
   340→    blobs: Vec<Blob<T::EthSpec>>,
   341→    proofs: Vec<KzgProofs<T::EthSpec>>,
   342→    custody_columns_indices: &[ColumnIndex],
   343→) -> Result<Vec<KzgVerifiedCustodyDataColumn<T::EthSpec>>, FetchEngineBlobError> {
   344→    let kzg = chain_adapter.kzg().clone();
   345→    let spec = chain_adapter.spec().clone();
   346→    let chain_adapter_cloned = chain_adapter.clone();
   347→    let custody_columns_indices = custody_columns_indices.to_vec();
   348→    let current_span = Span::current();
   349→    chain_adapter
   350→        .executor()
   351→        .spawn_blocking_handle(
   352→            move || {
   353→                let _guard = current_span.enter();
   354→                let mut timer = metrics::start_timer_vec(
   355→                    &metrics::DATA_COLUMN_SIDECAR_COMPUTATION,
   356→                    &[&blobs.len().to_string()],
   357→                );
   358→
   359→                let blob_refs = blobs.iter().collect::<Vec<_>>();
   360→                let cell_proofs = proofs.into_iter().flatten().collect();
   361→                let data_columns_result =
   362→                    blobs_to_data_column_sidecars(&blob_refs, cell_proofs, &block, &kzg, &spec)
   363→                        .discard_timer_on_break(&mut timer);
   364→                drop(timer);
   365→
   366→                // This filtering ensures we only import and publish the custody columns.
   367→                // `DataAvailabilityChecker` requires a strict match on custody columns count to
   368→                // consider a block available.
   369→                let mut custody_columns = data_columns_result
   370→                    .map(|data_columns| {
   371→                        data_columns
   372→                            .into_iter()
   373→                            .filter(|col| custody_columns_indices.contains(&col.index))
   374→                            .map(|col| {
   375→                                KzgVerifiedCustodyDataColumn::from_asserted_custody(
   376→                                    KzgVerifiedDataColumn::from_execution_verified(col),
   377→                                )
   378→                            })
   379→                            .collect::<Vec<_>>()
   380→                    })
   381→                    .map_err(FetchEngineBlobError::DataColumnSidecarError)?;
   382→
   383→                // Only consider columns that are not already observed on gossip.
   384→                if let Some(observed_columns) = chain_adapter_cloned.data_column_known_for_proposal(
   385→                    ProposalKey::new(block.message().proposer_index(), block.slot()),
   386→                ) {
   387→                    custody_columns.retain(|col| !observed_columns.contains(&col.index()));
   388→                    if custody_columns.is_empty() {
   389→                        return Ok(vec![]);
   390→                    }
   391→                }
   392→
   393→                // Only consider columns that are not already known to data availability.
   394→                if let Some(known_columns) =
   395→                    chain_adapter_cloned.cached_data_column_indexes(&block_root)
   396→                {
   397→                    custody_columns.retain(|col| !known_columns.contains(&col.index()));
   398→                    if custody_columns.is_empty() {
   399→                        return Ok(vec![]);
   400→                    }
   401→                }
   402→
   403→                Ok(custody_columns)
   404→            },
   405→            "compute_custody_columns_to_import",
   406→        )
   407→        .ok_or(FetchEngineBlobError::RuntimeShutdown)?
   408→        .await
   409→        .map_err(FetchEngineBlobError::TokioJoin)?
   410→}
   411→
   412→fn build_blob_sidecars<E: EthSpec>(
   413→    block: &Arc<SignedBeaconBlock<E, FullPayload<E>>>,
   414→    response: Vec<Option<BlobAndProofV1<E>>>,
   415→    signed_block_header: SignedBeaconBlockHeader,
   416→    kzg_commitments_inclusion_proof: &FixedVector<Hash256, E::KzgCommitmentsInclusionProofDepth>,
   417→) -> Result<Vec<KzgVerifiedBlob<E>>, FetchEngineBlobError> {
   418→    let mut sidecars = vec![];
   419→    for (index, blob_and_proof) in response
   420→        .into_iter()
   421→        .enumerate()
   422→        .filter_map(|(index, opt_blob)| Some((index, opt_blob?)))
   423→    {
   424→        let blob_sidecar = BlobSidecar::new_with_existing_proof(
   425→            index,
   426→            blob_and_proof.blob,
   427→            block,
   428→            signed_block_header.clone(),
   429→            kzg_commitments_inclusion_proof,
   430→            blob_and_proof.proof,
   431→        )
   432→        .map_err(FetchEngineBlobError::BlobSidecarError)?;
   433→
   434→        sidecars.push(KzgVerifiedBlob::from_execution_verified(
   435→            Arc::new(blob_sidecar),
   436→            timestamp_now(),
   437→        ));
   438→    }
   439→
   440→    Ok(sidecars)
   441→}
   442→

